// Once
// Обёртка: функция вызывается только один раз

function once(fn) {
  // TODO: implement
  return fn;
}

solution:
function once(fn) {
  let called = false;
  let result;
  return function (...args) {
    if (!called) {
      called = true;
      result = fn.apply(this, args);
    }
    return result;
  };
}

