// Curry for Three
// curry3(fn): вызов целиком или по одному аргументу

function curry3(fn) {
  // TODO: implement
  return fn;
}

solution:
function curry3(fn) {
  return function a(...args) {
    if (args.length >= 3) return fn(...args);
    return function (...next) { return a(...args, ...next); };
  };
}

