// Unique Values
// Убери дубликаты, сохранив порядок

function unique(arr) {
  // TODO: implement
  return arr;
}

solution:
function unique(arr) {
  const seen = new Set();
  const out = [];
  for (const v of arr) {
    if (!seen.has(v)) { seen.add(v); out.push(v); }
  }
  return out;
}

