// Debounce
// fn срабатывает только после ms миллисекунд тишины

function debounce(fn, ms) {
  // TODO: implement
  return fn;
}

solution:
function debounce(fn, ms) {
  let timer;
  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), ms);
  };
}

