// With Timeout
// promise или Error('timeout') через ms

async function withTimeout(promise, ms) {
  // TODO: implement
  return promise;
}

solution:
async function withTimeout(promise, ms) {
  return Promise.race([
    promise,
    new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), ms)),
  ]);
}

