// Count External Links
// Сколько ссылок внутри #content ведут на другой домен

function countExternal() {
  // TODO: implement
  return 0;
}

console.log('external links:', countExternal());

solution:
function countExternal() {
  const links = document.querySelectorAll('#content a');
  let n = 0;
  links.forEach((a) => {
    const href = a.getAttribute('href') || '';
    if (href.startsWith('https://')) {
      const u = new URL(href);
      if (u.hostname !== location.hostname) n += 1;
    }
  });
  return n;
}

