// Retry with Backoff
// Повторяй fn до times попыток, пауза delayMs между ними

async function retry(fn, times, delayMs) {
  // TODO: implement
  return fn();
}

solution:
async function retry(fn, times, delayMs) {
  let lastErr;
  for (let i = 1; i <= times; i++) {
    try {
      return await fn();
    } catch (e) {
      lastErr = e;
      if (i < times) await new Promise((r) => setTimeout(r, delayMs));
    }
  }
  throw lastErr;
}
